from data1 import talk,svg,person,F
D=dict
B='#e3f2fd'
V=[
D(n='21',lines=['punarapi jananaṃ punarapi maraṇaṃ','punarapi jananījaṭhare śayanam |','iha saṃsāre bahudustāre','kṛpayā\'pāre pāhi murāre ‖21‖'],theme='AGAIN BIRTH, AGAIN DEATH',
 svg=svg('A wheel turning endlessly: a baby, a man, an old man, a funeral fire, and a baby again, with a hand reaching out to Krishna',
  '<circle cx="90" cy="84" r="56" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="10 6"/>'+person(90,40,'#ffd60a','#f2c79b',.5)+person(140,92,'#1d6fb8','#f2c79b',.6)+person(90,148,'#999','#e0c09b',.6)+'<path d="M28 90 h20 l-3 6 h-14z" fill="#7a5a3a"/><path d="M34 90 q4 -12 8 0" fill="#ff8c1a"/><circle cx="196" cy="40" r="14" fill="#4a7fd0" stroke="#111" stroke-width="2"/><text x="196" y="70" text-anchor="middle" '+F+' font-size="9">MURĀRI</text><text x="196" y="84" text-anchor="middle" '+F+' font-size="9">SAVE ME</text>',B),
 mean='Again birth, again death, again lying in a mother\'s womb. In this saṃsāra, so very hard to cross and so boundless, save me by Your grace, O Murāri.',
 plain='Born, dying, born again, over and over. This cycle is endless and hard to escape. Save me by Your grace, O Kṛṣṇa.',
 words=[('punar api','<b>again and again</b>'),('jananam · maraṇam','<b>birth</b> · <b>death</b>'),('jananī-jaṭhare śayanam','<b>lying in a mother\'s womb</b>'),('bahu-dustāre','<b>very hard to cross</b>'),('apāre','<b>boundless</b>'),('pāhi murāre','<b>save me, O Murāri</b>')],
 deep='<p><b>The best-known verse after the refrain.</b> "Punarapi jananaṃ punarapi maraṇaṃ": the rolling repetition makes you feel the endless wheel of rebirth, <i>saṃsāra</i>.</p><p><b>A prayer, not a lecture.</b> For the first time the hymn turns into a direct cry: <i>pāhi murāre</i>, "save me, Murāri". The teacher of knowledge asks for grace.</p><p><b>Knowledge and grace.</b> Śaṅkara\'s Advaita says knowledge frees; this verse says grace makes that knowledge possible. The two are not enemies.</p>',
 cards=('💡 Saṃsāra','The flowing round of birth, death and rebirth, driven by karma and ignorance.','💡 Murāri','"Enemy of Mura": Kṛṣṇa, who destroyed the demon Mura.'),
 inner='When you feel trapped in the same circles, it is all right to ask for help. Grace is part of the way out.',
 talk=('Even Śaṅkara asks to be saved?','In this verse, yes. The great teacher of knowledge turns to grace. That\'s why this hymn touches everyone.'),
 key='Born again, dying again: <b>save me by Your grace, Murāri</b>.'),
D(n='22',lines=['rathyācarpaṭaviracitakanthaḥ','puṇyāpuṇyavivarjitapanthaḥ |','yogī yoganiyojitacitto','ramate bālonmattavadeva ‖22‖'],theme='THE YOGĪ IN RAGS',
 svg=svg('A happy yogi in a patched cloak sewn from street rags, playing like a child, with a glowing heart',
  '<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="50" r="14" fill="#f2c79b"/><path d="M80 140 q30 -80 60 0z" fill="#c9a26b"/></g>'+''.join(f'<rect x="{88+16*(k%3)}" y="{94+14*(k//3)}" width="14" height="12" fill="{c}" stroke="#111" stroke-width="1"/>' for k,c in enumerate(['#e63946','#4aa3df','#ffd60a','#2a9d6f','#f08aa6','#999']))+'<circle cx="110" cy="80" r="5" fill="#ffd60a"/><path d="M104 54 q6 6 12 0" fill="none" stroke="#111" stroke-width="2"/><circle cx="170" cy="130" r="8" fill="#e63946" stroke="#111"/><text x="110" y="22" text-anchor="middle" '+F+' font-size="11">LIKE A CHILD</text>',B),
 mean='His only cloak is stitched from rags picked up on the street; his path is beyond merit and sin; with his mind joined in yoga, the yogī delights like a child, or like one who is mad.',
 plain='The real yogī wears rags from the street, has gone beyond "good deeds" and "bad deeds", and plays happily like a child or a madman, his mind in the Lord.',
 words=[('rathyā-carpaṭa','<b>rags from the street</b>'),('viracita-kanthaḥ','<b>with a patched cloak made of them</b>'),('puṇya-apuṇya','<b>merit and demerit</b>'),('vivarjita-panthaḥ','<b>whose path is free of them</b>'),('yoga-niyojita-citta','<b>mind fixed in yoga</b>'),('bāla-unmatta-vat','<b>like a child or a madman</b>')],
 deep='<p><b>The opposite of verse 14.</b> There, people wore holy costumes for the belly. Here is the real thing: a yogī in a patched cloak (<i>kanthā</i>) who cares nothing for appearances.</p><p><b>Beyond merit and sin.</b> The jñānī is not bound even by good karma; he acts without the sense "I am the doer". This is a high state, not permission to do wrong.</p><p><b>Child and madman.</b> Sacred texts often compare the free sage to a child (innocent, playful) and a madman (indifferent to opinion). Think of Śuka, or of Rāmakṛṣṇa.</p>',
 cards=('💡 Kanthā','A patched cloak; also the famous Bengali stitched quilt.','💡 Avadhūta','"One who has shaken off" all conventions: the free, wandering sage.'),
 inner='Freedom often looks foolish from outside. A heart at peace doesn\'t need the world\'s approval.',
 talk=('He acts like a madman?','To the world, maybe. Inside, he\'s at perfect peace, playing like a child in the Lord.'),
 key='Rags outside, bliss inside: <b>the real yogī plays like a child</b>.'),
D(n='23',lines=['kastvaṃ ko\'haṃ kuta āyātaḥ','kā me jananī ko me tātaḥ |','iti paribhāvaya sarvamasāraṃ','viśvaṃ tyaktvā svapnavicāram ‖23‖'],theme='LIKE A DREAM',
 svg=svg('A sleeper with a dream bubble containing a whole world, and a sunrise waking him',
  '<rect x="30" y="120" width="100" height="16" rx="4" fill="#fff" stroke="#111" stroke-width="2"/>'+'<g stroke="#111" stroke-width="2"><circle cx="44" cy="114" r="10" fill="#f2c79b"/></g><ellipse cx="110" cy="60" rx="60" ry="36" fill="#fff" stroke="#111" stroke-width="2"/><circle cx="70" cy="100" r="6" fill="#fff" stroke="#111"/><circle cx="58" cy="108" r="3" fill="#fff" stroke="#111"/>'+person(100,76,'#e05a8a','#f2c79b',.5)+person(124,76,'#1d6fb8','#f2c79b',.5)+'<circle cx="196" cy="130" r="14" fill="#ffd60a"/><text x="110" y="20" text-anchor="middle" '+F+' font-size="10">A DREAM WORLD</text>',B),
 mean='Who are you? Who am I? From where have I come? Who is my mother, who my father? Reflect in this way; see everything as without substance, and let go of the world as a thing of dreams.',
 plain='Ask: who am I, where did I come from, who are my parents really? See that it is all passing, like a dream, and let it go.',
 words=[('kas tvam · ko \'ham','<b>who are you?</b> · <b>who am I?</b>'),('kuta āyātaḥ','<b>from where have I come?</b>'),('jananī · tātaḥ','<b>mother</b> · <b>father</b>'),('paribhāvaya','<b>reflect deeply</b>'),('asāram','<b>without substance</b>'),('svapna-vicāram','<b>a dream-thought</b>')],
 deep='<p><b>The questions return.</b> Verse 8 asked them in the middle of the hymn; verse 23 asks again, deeper: not "who is your wife?" but "who are <i>you</i>, who am <i>I</i>?"</p><p><b>The dream.</b> In a dream we have parents, homes, joys and fears, all quite real until we wake. Vedānta says the waking world is like that before the Self is known.</p><p><b>Not cold.</b> Seeing the world as dream-like does not mean not caring. It means not drowning: loving fully, but without clinging.</p>',
 cards=('💡 Svapna','Dream: one of the three states, with waking and deep sleep; see Oṃ in our Mahimna Part 3.','💡 Vicāra','Inquiry: careful reflection, the method of Self-knowledge.'),
 inner='Hold the world the way you hold a dream as you wake: gently, gratefully, and without grasping.',
 talk=('If it\'s a dream, why bother?','Because waking up is the point. You play your part well, and you don\'t mistake the dream for the waking.'),
 key='"Who am I?" Ask it, <b>and see the world as a dream you can wake from</b>.'),
D(n='24',lines=['tvayi mayi cānyatraiko viṣṇuḥ','vyarthaṃ kupyasi mayyasahiṣṇuḥ |','bhava samacittaḥ sarvatra tvaṃ','vāñchasyacirādyadi viṣṇutvam ‖24‖'],theme='ONE VIṢṆU IN ALL',
 svg=svg('Three people of different kinds, each with the same small blue light in the heart, and an angry face fading away',
  ''.join(person(40+60*k,124,c)+f'<circle cx="{40+60*k}" cy="114" r="6" fill="#4a7fd0" stroke="#111"/>' for k,c in enumerate(['#ff8c1a','#2a9d6f','#e05a8a']))+'<text x="110" y="30" text-anchor="middle" '+F+' font-size="12" fill="#1d6fb8">THE SAME VIṢṆU IN ALL</text>',B),
 mean='In you, in me, and everywhere else there is one Viṣṇu. Impatient, you get angry with me for nothing. Be even-minded towards all, everywhere, if you wish to reach Viṣṇu\'s state soon.',
 plain='The same Lord lives in you, in me, in everyone. So why be angry with me? Treat all alike, if you want to reach God soon.',
 words=[('tvayi mayi ca anyatra','<b>in you, in me, and elsewhere</b>'),('ekaḥ viṣṇuḥ','<b>one Viṣṇu</b>'),('vyartham kupyasi','<b>you are angry in vain</b>'),('asahiṣṇuḥ','<b>impatient</b>, intolerant'),('sama-cittaḥ','<b>even-minded</b>'),('viṣṇutvam','<b>the state of Viṣṇu</b>')],
 deep='<p><b>Ethics from oneness.</b> If one Lord lives in all, anger at another is anger at Him. Śaṅkara\'s philosophy of oneness becomes a rule for daily life: patience.</p><p><b>Sama-citta.</b> Even-mindedness: the Gītā\'s great word (<i>samatvaṃ yoga ucyate</i>, "evenness is yoga", 2.48).</p><p><b>Viṣṇutvam.</b> To become like Viṣṇu, all-pervading, is to see Him in everyone.</p>',
 cards=('💡 Viṣṇu','"The all-pervader": the name itself means the one who is everywhere.','💡 Samatva','Evenness of mind: Gītā 2.48, "yoga is evenness".'),
 inner='When you are angry with someone, remember who lives in them.',
 talk=('So I can never be angry?','The verse says anger at others is anger at the same Lord in them. Patience comes from seeing that.'),
 key='One Viṣṇu in you, in me, in all: <b>so why be angry?</b>'),
D(n='25',lines=['śatrau mitre putre bandhau','mā kuru yatnaṃ vigrahasandhau |','sarvasminnapi paśyātmānaṃ','sarvatrotsṛja bhedājñānam ‖25‖'],theme='FRIEND AND FOE',
 svg=svg('Two figures, one labelled friend and one labelled foe, with the same Self shining in both and a dotted line of difference being erased',
  person(60,124,'#2a9d6f')+person(160,124,'#c0392b')+'<circle cx="60" cy="114" r="6" fill="#ffd60a"/><circle cx="160" cy="114" r="6" fill="#ffd60a"/><path d="M110 40 v110" stroke="#999" stroke-width="3" stroke-dasharray="6 6"/><text x="60" y="40" text-anchor="middle" '+F+' font-size="10">FRIEND</text><text x="160" y="40" text-anchor="middle" '+F+' font-size="10">FOE</text><text x="110" y="24" text-anchor="middle" '+F+' font-size="11">ONE SELF</text>',B),
 mean='Towards enemy or friend, son or relative, do not strive for quarrel or for alliance. See the Self in everything, and everywhere give up the ignorance that sees difference.',
 plain='Don\'t spend your life making enemies or forming alliances. See the same Self in everyone, and drop the ignorance that divides.',
 words=[('śatru · mitra','<b>enemy</b> · <b>friend</b>'),('putra · bandhu','<b>son</b> · <b>relative</b>'),('vigraha · sandhi','<b>war</b> · <b>peace-making</b>'),('mā kuru yatnam','<b>do not strive</b>'),('paśya ātmānam','<b>see the Self</b>'),('bheda-ajñāna','<b>the ignorance of difference</b>')],
 deep='<p><b>Politics of the heart.</b> <i>Vigraha</i> and <i>sandhi</i>, war and treaty, are terms from statecraft. Śaṅkara uses them for family and friends: don\'t make life a game of forming camps.</p><p><b>Bheda.</b> The ignorance that sees separateness is, for Advaita, the root problem. Seeing the one Self in all dissolves it.</p><p><b>Carrying on from 24.</b> If there is one Viṣṇu in all, there are no true enemies, only the same Self in different forms.</p>',
 cards=('💡 Advaita','"Non-duality": the teaching that the Self in all is one.','💡 Ātman','The Self: in Advaita, identical with Brahman.'),
 inner='Stop dividing people into camps. The same light looks out of every face.',
 talk=('Treat enemies like friends?','Don\'t spend your life fighting or plotting. See the same Self in both. That\'s Śaṅkara\'s cure for division.'),
 key='See the one Self in friend and foe: <b>drop the ignorance of difference</b>.'),
D(n='26',lines=['kāmaṃ krodhaṃ lobhaṃ mohaṃ','tyaktvā\'tmānaṃ bhāvaya ko\'ham |','ātmajñānavihīnā mūḍhāḥ','te pacyante narakanigūḍhāḥ ‖26‖'],theme='THE FOUR THIEVES',
 svg=svg('Four shadowy thieves labelled lust, anger, greed and delusion leaving a house where a person sits asking who am I',
  ''.join(f'<g transform="translate({30+40*k} 120)"><circle cy="-30" r="10" fill="#555"/><path d="M-14 20 q14 -46 28 0z" fill="#555"/></g><text x="{30+40*k}" y="156" text-anchor="middle" {F} font-size="8">{t}</text>' for k,t in enumerate(['KĀMA','KRODHA','LOBHA','MOHA']))+person(196,110,'#1d6fb8','#f2c79b',.7)+'<text x="196" y="50" text-anchor="middle" '+F+' font-size="9">KO\'HAM?</text>',B),
 mean='Giving up lust, anger, greed and delusion, reflect on the Self: "who am I?" Fools without knowledge of the Self are cooked in a hidden hell.',
 plain='Drop desire, anger, greed and confusion, and ask "who am I?". Without knowing the Self, people suffer as if in hell.',
 words=[('kāma','<b>lust, desire</b>'),('krodha','<b>anger</b>'),('lobha','<b>greed</b>'),('moha','<b>delusion</b>'),('ko \'ham','"<b>who am I?</b>"'),('naraka-nigūḍhāḥ','<b>hidden in hell</b>')],
 deep='<p><b>The inner enemies.</b> Indian thought lists six inner enemies (<i>ariṣaḍvarga</i>): lust, anger, greed, delusion, pride and jealousy. This verse names the first four.</p><p><b>Ko\'ham.</b> "Who am I?" is the inquiry at the heart of Advaita, later made famous by Ramaṇa Maharṣi. A variant reading adds <i>paśyati so\'ham</i>: "he sees, I am That".</p><p><b>Hell now.</b> "Cooked in hidden hell" can be read as our inner state: a mind ruled by these four is already burning.</p>',
 cards=('💡 Ariṣaḍvarga','The six inner enemies: kāma, krodha, lobha, moha, mada, mātsarya.','💡 So\'ham','"I am That": the variant line, and a famous mantra of the breath.'),
 inner='Lust, anger, greed and confusion are the four thieves of peace. The question "who am I?" turns on the light.',
 talk=('What\'s the hidden hell?','Many read it as the mind ruled by desire and anger: already a kind of hell. Self-knowledge is the way out.'),
 key='Drop the four thieves <b>and ask: who am I?</b>',
 note='The source text records a variant line, paśyati so\'ham ("he sees: I am That").'),
D(n='27',lines=['geyaṃ gītānāmasahasraṃ','dhyeyaṃ śrīpatirūpamajasram |','neyaṃ sajjanasaṅge cittaṃ','deyaṃ dīnajanāya ca vittam ‖27‖'],theme='FOUR THINGS TO DO',
 svg=svg('Four small panels: a singer with the Gita, a meditator before Vishnu, a group of good people, and a hand giving to the poor',
  ''.join(f'<rect x="{6+54*k}" y="30" width="50" height="110" rx="6" fill="{c}" stroke="#111" stroke-width="2"/><text x="{31+54*k}" y="152" text-anchor="middle" {F} font-size="8">{t}</text>' for k,(c,t) in enumerate([('#fff3b0','SING'),('#dcecff','MEDITATE'),('#ddf5ea','GOOD COMPANY'),('#ffe0e0','GIVE')]))
  +'<text x="31" y="90" text-anchor="middle" font-size="22">🎵</text><circle cx="85" cy="80" r="12" fill="#4a7fd0" stroke="#111"/>'+person(139,104,'#2a9d6f','#f2c79b',.5)+'<text x="193" y="90" text-anchor="middle" font-size="22">🤲</text>',B),
 mean='The Gītā and the Thousand Names are to be sung; the form of the Lord of Śrī is to be meditated on, always; the mind is to be led into the company of the good; and wealth is to be given to the needy.',
 plain='Sing the Gītā and the Viṣṇu Sahasranāma; always remember the Lord\'s form; keep good company; and share your wealth with those in need.',
 words=[('geyam','<b>to be sung</b>'),('gītā-nāma-sahasram','the <b>Gītā and the Thousand Names</b>'),('dhyeyam','<b>to be meditated on</b>'),('śrīpati-rūpam','the <b>form of the Lord of Śrī</b>: Viṣṇu'),('neyam cittam','the <b>mind is to be led</b>'),('deyam vittam','<b>wealth is to be given</b>')],
 deep='<p><b>A daily rule in one verse.</b> Four short commands, each starting with a verb form ending in <i>-yam</i>: sing, meditate, lead the mind, give. Many people memorise this verse as a life plan.</p><p><b>The Thousand Names.</b> The <b>Viṣṇu Sahasranāma</b>, from the Mahābhārata; Śaṅkara wrote a commentary on it as well as on the Gītā.</p><p><b>From the head to the hand.</b> The list moves from speech (sing) to mind (meditate) to company (lead the mind) to action (give). Spiritual life ends in generosity.</p>',
 cards=('💡 Viṣṇu Sahasranāma','The thousand names of Viṣṇu, taught by Bhīṣma in the Mahābhārata.','💡 Dāna','Giving: one of the foundations of dharma.'),
 inner='Sing, remember, choose your company, give. A whole spiritual life fits in these four.',
 talk=('This one\'s practical!','Very. Four things anyone can do, starting today. Many families teach children this verse first.'),
 key='Sing, meditate, keep good company, <b>give to those in need</b>.'),
D(n='28',lines=['sukhataḥ kriyate rāmābhogaḥ','paścāddhanta śarīre rogaḥ |','yadyapi loke maraṇaṃ śaraṇaṃ','tadapi na muñcati pāpācaraṇam ‖28‖','· · ·','arthamanarthaṃ bhāvaya nityaṃ','nāsti tataḥ sukhaleśaḥ satyam |','putrādapi dhanabhājāṃ bhītiḥ','sarvatraiṣā vihitā rītiḥ ‖29‖'],theme='PLEASURE AND WEALTH',
 svg=svg('A feast leading to a sick bed, and a rich man guarding his treasure chest anxiously even from his son',
  '<rect x="10" y="40" width="60" height="30" rx="4" fill="#ffe3c4" stroke="#111" stroke-width="2"/><path d="M70 55 h20" stroke="#111" stroke-width="2"/><path d="M86 50 l6 5 l-6 5" fill="none" stroke="#111" stroke-width="2"/><rect x="94" y="44" width="40" height="22" fill="#fff" stroke="#111" stroke-width="2"/><text x="40" y="34" text-anchor="middle" '+F+' font-size="9">PLEASURE</text><text x="114" y="38" text-anchor="middle" '+F+' font-size="9">ILLNESS</text>'
  '<rect x="130" y="110" width="50" height="34" fill="#c9a26b" stroke="#111" stroke-width="2"/>'+person(110,140,'#ffd60a','#f2c79b',.7)+person(200,140,'#1d6fb8','#f2c79b',.6)+'<text x="150" y="102" text-anchor="middle" '+F+' font-size="9">FEARFUL WEALTH</text>',B),
 mean='(28) Pleasures of the body are enjoyed with ease; afterwards, alas, comes disease. Though in this world death is the final end, still people do not give up wrong conduct. (29) Always regard wealth as a source of trouble; truly, there is not a trace of happiness in it. Those who hold wealth fear even their own sons: this is the way everywhere.',
 plain='Pleasures are easy; illness follows. Death is certain, yet people don\'t change. Money, too, brings worry, not happiness: the rich fear even their own children.',
 words=[('sukhataḥ','<b>easily</b>, for pleasure'),('rāmā-bhoga','<b>sensual enjoyment</b>'),('maraṇaṃ śaraṇam','<b>death is the final resort</b>'),('pāpa-ācaraṇa','<b>wrong conduct</b>'),('artham anartham','<b>wealth as trouble</b>'),('bhītiḥ','<b>fear</b>')],
 deep='<p><b>Two portraits.</b> Verse 28 shows pleasure followed by illness; verse 29 shows wealth followed by fear. Both are about what happens when we chase things for their own sake.</p><p><b>Artham anartham.</b> A play on words: <i>artha</i> (wealth, purpose) becomes <i>anartha</i> (trouble, meaninglessness) when it rules us.</p><p><b>For balance.</b> Indian tradition honours <i>artha</i> and <i>kāma</i> as legitimate goals of life, within dharma. These verses warn against letting them take over.</p>',
 cards=('💡 Puruṣārthas','The four aims of life: dharma, artha, kāma, mokṣa.','💡 Anartha','Trouble, harm: the shadow side of wealth.'),
 inner='Enjoy what comes, earn what you need, but don\'t let pleasure or money become the master.',
 talk=('Afraid of their own sons?','Over inheritance and money, sadly, it happens. Śaṅkara says wealth brings worry as often as joy.'),
 key='Pleasure brings illness, wealth brings fear: <b>neither is the goal</b>.'),
D(n='30',lines=['prāṇāyāmaṃ pratyāhāraṃ','nityānityavivekavicāram |','jāpyasameta samādhividhānaṃ','kurvavadhānaṃ mahadavadhānam ‖30‖'],theme='WITH GREAT CARE',
 svg=svg('A meditator seated calmly, with labels for breath, withdrawing the senses, discernment, japa and absorption',
  person(110,124,'#1d6fb8')+'<circle cx="110" cy="76" r="26" fill="none" stroke="#ffd60a" stroke-width="3"/>'+''.join(f'<text x="{x}" y="{y}" text-anchor="middle" {F} font-size="8">{t}</text>' for x,y,t in [(40,40,'PRĀṆĀYĀMA'),(180,40,'PRATYĀHĀRA'),(30,100,'VIVEKA'),(190,100,'JAPA'),(110,22,'SAMĀDHI')]),B),
 mean='Breath control, withdrawal of the senses, inquiry discerning the eternal from the passing, and the practice of absorption together with japa: do these with care, with great care.',
 plain='Practise breath control, calm the senses, think clearly about what lasts and what doesn\'t, repeat God\'s name, and go deep in meditation, carefully, very carefully.',
 words=[('prāṇāyāma','<b>breath control</b>'),('pratyāhāra','<b>withdrawal of the senses</b>'),('nitya-anitya-viveka','<b>discerning eternal from passing</b>'),('jāpya','<b>japa</b>, repeating a mantra'),('samādhi-vidhāna','<b>the practice of absorption</b>'),('mahad avadhānam','<b>great care</b>, great attention')],
 deep='<p><b>A yoga syllabus.</b> The verse lists steps from Patañjali\'s yoga (prāṇāyāma, pratyāhāra, samādhi) with Vedānta\'s <i>viveka</i>, discrimination between the eternal and the passing, and devotion\'s <i>japa</i>.</p><p><b>Avadhāna.</b> Attention, care. The repetition, "with care, with great care", is the teacher\'s final emphasis: spiritual practice must be done attentively, not mechanically.</p><p><b>Not only feeling.</b> After all the talk of devotion, the hymn insists on disciplined practice too.</p>',
 cards=('💡 Aṣṭāṅga yoga','Patañjali\'s eight limbs, including prāṇāyāma, pratyāhāra and samādhi.','💡 Viveka','Discrimination: Śaṅkara\'s first qualification for a seeker.'),
 inner='Practice done carelessly is a habit. Practice done with great care becomes a path.',
 talk=('Why say "care" twice?','It\'s the teacher underlining it. Breath, senses, thought, mantra: all of them need real attention.'),
 key='Breath, senses, discernment, japa, absorption: <b>with great care</b>.'),
D(n='31',lines=['gurucaraṇāmbujanirbharabhaktaḥ','saṃsārādacirādbhava muktaḥ |','sendriyamānasaniyamādevaṃ','drakṣyasi nijahṛdayasthaṃ devam ‖31‖'],theme='AT THE GURU\'S FEET',
 svg=svg('A disciple bowing at the lotus feet of a seated teacher, and a small radiant figure of the Lord shining in the disciple\'s heart',
  '<g stroke="#111" stroke-width="2.5"><circle cx="150" cy="50" r="14" fill="#f2c79b"/><path d="M120 120 q30 -70 60 0z" fill="#ff8c1a"/></g><path d="M126 126 q8 -8 16 0 q-8 8 -16 0z M158 126 q8 -8 16 0 q-8 8 -16 0z" fill="#f08aa6" stroke="#111"/>'
  '<g stroke="#111" stroke-width="2.5"><circle cx="70" cy="118" r="11" fill="#f2c79b"/><path d="M40 146 q20 -26 60 -18 l6 18z" fill="#1d6fb8"/></g><circle cx="74" cy="134" r="6" fill="#ffd60a"/><text x="110" y="22" text-anchor="middle" '+F+' font-size="11">THE LORD IN YOUR OWN HEART</text>',B),
 mean='Wholly devoted to the lotus feet of the guru, be free from saṃsāra soon. In this way, through the discipline of the senses and the mind, you will see the Lord who dwells in your own heart.',
 plain='Devote yourself to your teacher, master your senses and mind, and you\'ll soon be free; you will see God living in your own heart.',
 words=[('guru-caraṇa-ambuja','<b>the lotus feet of the guru</b>'),('nirbhara-bhaktaḥ','<b>fully devoted</b>'),('acirāt','<b>soon</b>'),('bhava muktaḥ','<b>be free</b>'),('sa-indriya-mānasa-niyamāt','<b>by restraint of senses and mind</b>'),('nija-hṛdaya-stham devam','<b>the Lord in your own heart</b>')],
 deep='<p><b>The guru.</b> In Indian tradition, the teacher is the bridge to the truth: Bhaja Govindam itself began with a teacher stopping to help an old man.</p><p><b>Where God is found.</b> After all the warnings, the last teaching verse ends with a promise: <i>drakṣyasi nijahṛdayasthaṃ devam</i>, "you will see the Lord in your own heart". Not far away; within.</p><p><b>Two wings.</b> Devotion (to the guru) and discipline (of senses and mind): the verse joins bhakti and yoga, and the result is jñāna, seeing.</p>',
 cards=('💡 Guru','"The one who removes darkness": the teacher of the path.','💡 Hṛdaya','The heart: in Vedānta, the seat of the Self.'),
 inner='The journey ends where it began: at home, in your own heart.',
 talk=('So God is inside us?','That\'s the promise of the last teaching verse: discipline the mind, love the teacher, and you\'ll see the Lord in your own heart.'),
 key='Serve the guru, steady the mind: <b>see the Lord in your own heart</b>.'),
D(n='32',lines=['mūḍhaḥ kaścana vaiyākaraṇo','ḍukṛñkaraṇādhyayanadhurīṇaḥ |','śrīmacchaṅkarabhagavacchiṣyaiḥ','bodhita āsīcchodhitakaraṇaḥ ‖32‖','· · ·','bhajagovindaṃ bhajagovindaṃ','govindaṃ bhaja mūḍhamate |','nāmasmaraṇādanyamupāyaṃ','nahi paśyāmo bhavābdhitaraṇe ‖33‖'],theme='THE GRAMMARIAN AWAKENED',
 svg=svg('The old grammarian closing his book and smiling, folding his hands as the disciples sing and a flute-playing Govinda appears above',
  person(70,124,'#999','#e0c09b')+'<rect x="40" y="132" width="60" height="10" fill="#fff3b0" stroke="#111" stroke-width="2"/><path d="M64 98 q6 6 12 0" fill="none" stroke="#111" stroke-width="2"/>'+person(150,124,'#ff8c1a','#f2c79b',.7)+person(180,128,'#ff8c1a','#f2c79b',.6)+'<circle cx="110" cy="34" r="14" fill="#4a7fd0" stroke="#111" stroke-width="2"/><path d="M92 40 l36 -6" stroke="#7a5a3a" stroke-width="3"/><text x="110" y="66" text-anchor="middle" '+F+' font-size="10">THE NAME</text>',B),
 mean='(32) A certain foolish grammarian, absorbed in studying "ḍukṛñ karaṇe", was awakened by the disciples of Śrī Śaṅkara Bhagavatpāda, and his mind was purified. (33) Worship Govinda, worship Govinda, worship Govinda, O foolish mind! Other than remembering the Name, we see no other way to cross the ocean of becoming.',
 plain='So the old grammarian was awakened by Śaṅkara\'s disciples, his mind made pure. Worship Govinda: the remembrance of His Name is the only way across.',
 words=[('vaiyākaraṇaḥ','a <b>grammarian</b>'),('adhyayana-dhurīṇaḥ','<b>absorbed in study</b>'),('bodhitaḥ','<b>awakened</b>, taught'),('śodhita-karaṇaḥ','<b>with purified senses and mind</b>'),('nāma-smaraṇa','<b>remembrance of the Name</b>'),('bhava-abdhi-taraṇe','<b>for crossing the ocean of becoming</b>')],
 deep='<p><b>The story ends.</b> Verse 32 closes the frame opened in Part 1: the old man cramming "ḍukṛñ karaṇe" is awakened. The hymn tells us its own outcome: it worked.</p><p><b>The refrain returns.</b> Verse 33 repeats "bhaja govindaṃ" and adds the hymn\'s final answer: <i>nāma-smaraṇa</i>, remembering the Lord\'s Name, is the way across.</p><p><b>From grammar to the Name.</b> A beautiful circle: the old man was obsessed with words; he is saved by one word, the Name of God.</p>',
 cards=('💡 Nāma-smaraṇa','Remembering the divine Name: the heart of bhakti practice in every Indian tradition.','💡 Bhavābdhi','"The ocean of becoming": saṃsāra pictured as a sea to be crossed.'),
 inner='He spent his life on words, and was saved by one Name. Whatever your life has been, it is never too late to turn.',
 talk=('So the old man was saved?','The hymn says so: awakened, his mind purified. And the last word is the same as the first: bhaja govindaṃ.'),
 key='Not grammar but the Name: <b>bhaja govindaṃ, O mind</b>.',
 note='Verse 33\'s last word reads bhavābdhitaraṇe in the main text, with bhavataraṇe as a recorded variant.'),
]
